import re
from abc import ABCMeta, abstractmethod


class Connector(metaclass=ABCMeta):
    def __init__(self, port, baudrate=115200):
        self._exc = None
        self.port = port
        self._baudrate = baudrate
        self._reader_thread = None
        self._readline_timeout = 0.4
        self._connection_timeout = 300
        self._output_buffer = ""
        self.done = False

    @abstractmethod
    def open(self, timeout):
        raise NotImplementedError

    @abstractmethod
    def is_closed(self):
        raise NotImplementedError

    @abstractmethod
    def close(self):
        raise NotImplementedError

    @abstractmethod
    def in_waiting(self):
        raise NotImplementedError

    @abstractmethod
    def send_break(self):
        raise NotImplementedError

    def read_one_line(self):
        line = self._read_one_line()
        return self._sort_out_specials_in_msg(line)

    @abstractmethod
    def _read_one_line(self):
        raise NotImplementedError

    @abstractmethod
    def read_available(self):
        """Read all currently available data without blocking for newline."""
        raise NotImplementedError

    @staticmethod
    def _sort_out_specials_in_msg(msg):
        if msg.endswith("\r"):
            msg = msg[:-1]
        msg = msg.replace(" \r", "")
        msg = re.sub(r"\r.", "", msg)
        msg = re.sub(r"\x1B(?:[78]|[@-Z\\-_]|\[[0-?]*[ -\/]*[@-~])", "", msg)
        return msg

    def send(self, cmd):
        self._send(cmd + "\r")

    @abstractmethod
    def _send(self, cmd):
        raise NotImplementedError
